import {useState,type ReactNode} from 'react';
import {Brain,Pill,CloudSun,ChevronRight,BarChart3,Activity,Download,Plus,BookOpen,User,LogOut} from 'lucide-react';
import {type Data,type Day,type Mode,dateKey,dates,shiftDate,status,zone,validateDay} from './core';
import {reportData} from './report-data';
import {useT,symptomUr} from './i18n';
import {Card,Modal,Field,Notice} from './components';
import {checkInUr} from './checkin';

type Props={data:Data;mode:Mode;from:string;to:string};
const colors=['#ffe2ee','#ffc2dc','#ff9fc7','#f84d91'];
function Ring({parts,center,label}:{parts:{n:number;color:string}[];center:string|number;label:string}){const total=parts.reduce((n,p)=>n+p.n,0);let offset=0;const stops=parts.map(p=>{const start=offset;offset+=total?p.n/total*100:0;return `${p.color} ${start}% ${offset}%`});return <div className="pink-ring" role="img" aria-label={label+': '+center} style={{background:total?`conic-gradient(${stops.join(',')})`:'#efedf4'}}><div><strong>{center}</strong><span>{label}</span></div></div>}
function Row({icon,heading,sub,onClick}:{icon:ReactNode;heading:string;sub:string;onClick:()=>void}){return <button className="feature-row" onClick={onClick}><span className="feature-icon">{icon}</span><span><strong>{heading}</strong><small>{sub}</small></span><ChevronRight size={20}/></button>}
const articles=[{id:'migraine',image:'migraine-article.png',title:'Is migraine curable?',ur:'کیا مائیگرین کا علاج ممکن ہے؟',sub:'Understanding care and support',usub:'نگہداشت اور مدد کو سمجھیں',body:'There is currently no cure for migraine, but treatments can help manage symptoms. Discuss your experiences and treatment options with a healthcare professional.',ubody:'فی الحال مائیگرین کا مکمل علاج موجود نہیں، مگر علاج علامات کو سنبھالنے میں مدد دے سکتا ہے۔ اپنی کیفیت اور علاج کے اختیارات پر ماہر صحت سے گفتگو کریں۔',source:'https://www.ninds.nih.gov/health-information/disorders/migraine',sourceTitle:'National Institute of Neurological Disorders and Stroke'},{id:'diary',image:'diary-article.png',title:'Why keep a headache diary?',ur:'سر درد کی ڈائری کیوں رکھیں؟',sub:'Small observations, a clearer conversation',usub:'چھوٹے مشاہدات، واضح گفتگو',body:'Recording when headaches happen, associated symptoms and daily circumstances can help you describe your experience. Record headache-free days too. Diary patterns alone do not confirm a diagnosis or prove a cause.',ubody:'سر درد کے اوقات، ساتھ کی علامات اور روزانہ کے حالات درج کرنا اپنی کیفیت بیان کرنے میں مدد دیتا ہے۔ سر درد سے پاک دن بھی درج کریں۔ صرف ڈائری کے رجحانات تشخیص یا وجہ ثابت نہیں کرتے۔',source:'https://migrainetrust.org/live-with-migraine/self-management/keeping-a-migraine-diary/',sourceTitle:'The Migraine Trust'}];
export function ArticleCards({go}:{go:(s:string)=>void}){const t=useT();const [active,setActive]=useState<string|null>(null);const a=articles.find(a=>a.id===active);return <section className="article-section"><div className="row between"><h2>{t('Articles','مضامین')}</h2><button className="text-button" onClick={()=>go('learn')}>{t('See all','سب دیکھیں')}</button></div><div className="article-grid">{articles.map(a=><button className="article-card" key={a.id} onClick={()=>setActive(a.id)}><img loading="lazy" src={'./images/'+a.image} alt=""/><span><strong>{t(a.title,a.ur)}</strong><small>{t(a.sub,a.usub)}</small></span></button>)}</div>{a&&<Modal title={t(a.title,a.ur)} onClose={()=>setActive(null)}><img className="article-modal-image" src={'./images/'+a.image} alt=""/><p>{t(a.body,a.ubody)}</p><a href={a.source} target="_blank" rel="noreferrer">{a.sourceTitle} ↗</a></Modal>}</section>}
export function PinkDashboard(p:Props&{go:(s:string)=>void;onDate:(date:string)=>void;save:(d:Data)=>Promise<void>}){
 const t=useT(),today=dateKey(new Date(),zone(p.mode));const [selected,setSelected]=useState(today),[pressure,setPressure]=useState(false);const s=status(p.data,selected,zone(p.mode));const month=reportData(p.data,today.slice(0,7)+'-01',today,zone(p.mode));
 const pain=s.daily?.checkIn?.peakPain??(s.attacks.length?Math.max(...s.attacks.map(a=>a.pain)):null);const symptoms=[...new Set([...(s.daily?.checkIn?.symptoms??[]),...s.attacks.flatMap(a=>a.symptoms)])];const meds=s.daily?.checkIn?.medicine==='yes'||s.attacks.some(a=>a.medication||a.taken);const label=s.kind==='headache'?t('Headache','سر درد'):s.kind==='free'?t('Headache-free','سر درد نہیں'):s.kind==='unsure'?t('Not sure','پتا نہیں'):t('Not recorded','درج نہیں');
 return <div className="pink-dashboard"><div className="dashboard-primary"><section><h2>{selected===today?t('Today','آج'):selected}</h2><button className="today-overview" onClick={()=>p.onDate(selected)}><div><span className="pink-status">{label}{pain!==null?` · ${pain}/10`:''}</span><p><Brain size={20}/>{symptoms.length?symptoms.map(v=>t(v,checkInUr[v]??symptomUr[v]??v)).join(', '):t('Symptoms not recorded','علامات درج نہیں')}</p><p><Pill size={20}/>{meds?t('Medicine recorded','دوا درج ہے'):s.daily?.checkIn?.medicine==='no'?t('No medicine taken','کوئی دوا نہیں لی'):t('Medicine not recorded','دوا درج نہیں')}</p><small>{t('View or update this day','یہ دن دیکھیں یا ترمیم کریں')} →</small></div><img src="./images/brain-diary.png" alt=""/></button></section><section><h2>{t('Week','ہفتہ')}</h2><Card className="week-card"><div className="week-strip">{dates(shiftDate(today,-6),today).map(d=><button key={d} aria-label={d} aria-pressed={selected===d} className={selected===d?'selected':''} onClick={()=>setSelected(d)}><small>{new Intl.DateTimeFormat(t('en','ur'),{weekday:'short'}).format(new Date(d+'T12:00:00'))}</small><b>{d.slice(-2)}</b><span>{status(p.data,d,zone(p.mode)).kind==='headache'?'●':status(p.data,d,zone(p.mode)).kind==='free'?'✓':'—'}</span></button>)}</div><p><Pill size={19}/>{selected} · {meds?t('Medicine recorded','دوا درج ہے'):t('No medicine record','دوا کا ریکارڈ نہیں')}</p></Card></section><section><h2>{t('Pressure variation','فضائی دباؤ میں تبدیلی')}</h2><Row icon={<CloudSun/>} heading={t('My observations','میرے مشاہدات')} sub={t('Record pressure alongside your diary','ڈائری کے ساتھ فضائی دباؤ درج کریں')} onClick={()=>setPressure(true)}/></section><section><h2>{t('This month','اس ماہ')}</h2><Card className="month-card"><Ring parts={[{n:month.headache,color:'#ff9fc7'},{n:month.free,color:'#ffe2ee'},{n:month.unknown,color:'#c9bfdc'},{n:month.missing,color:'#efedf4'}]} center={month.recorded} label={t('recorded days','درج شدہ دن')}/><ul className="chart-legend"><li><b>{month.headache}</b>{t('Headache days','سر درد والے دن')}</li><li><b>{month.free}</b>{t('Headache-free','سر درد نہیں')}</li><li><b>{month.unknown}</b>{t('Not sure','پتا نہیں')}</li><li><b>{month.missing}</b>{t('Unrecorded','درج نہیں')}</li></ul></Card></section></div><div className="dashboard-secondary"><section><h2>{t('Reports','رپورٹس')}</h2><Row icon={<BarChart3/>} heading={t('Headache report','سر درد کی رپورٹ')} sub={t('Explore your recorded patterns','درج کردہ رجحانات دیکھیں')} onClick={()=>p.go('reports')}/><Row icon={<Activity/>} heading={t('Daily activity impact','روزمرہ کاموں پر اثر')} sub={t('Your observations, without a total score','آپ کے مشاہدات، بغیر مجموعی اسکور')} onClick={()=>p.go('reports')}/><a className="feature-row" href="https://headaches.org/resources/headache-tests" target="_blank" rel="noreferrer"><span className="feature-icon"><Brain/></span><span><strong>{t('MIDAS questionnaire','MIDAS سوالنامہ')}</strong><small>{t('Official external resource ↗','سرکاری بیرونی ذریعہ ↗')}</small></span></a></section><ArticleCards go={p.go}/></div>{pressure&&<PressureEditor data={p.data} save={p.save} close={()=>setPressure(false)}/>}</div>
}
function PressureEditor({data,save,close}:{data:Data;save:(d:Data)=>Promise<void>;close:()=>void}){const t=useT();const [date,setDate]=useState(dateKey()),[value,setValue]=useState<string>(()=>String(data.days.find(d=>d.date===dateKey())?.pressureHpa??'')),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Modal title={t('Pressure observations','فضائی دباؤ کے مشاہدات')} onClose={close}><p>{t('Enter a reading from your weather source. This records context; it does not predict attacks or measure sensitivity.','اپنے موسم کے ذریعے سے دباؤ درج کریں۔ یہ پس منظر کا ریکارڈ ہے؛ دوروں کی پیش گوئی یا حساسیت کی پیمائش نہیں۔')}</p><form onSubmit={async e=>{e.preventDefault();setError('');setBusy(true);try{const old=data.days.find(d=>d.date===date);const d:Day={...(old??{id:crypto.randomUUID(),date,headache:'unsure',sleep:null,quality:'',meals:'unknown',caffeine:null,exposures:'',notes:''}),pressureHpa:value===''?null:Number(value)};validateDay(d);await save({...data,days:[...data.days.filter(v=>v.date!==date),d]});close()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><Field label={t('Date','تاریخ')}><input required type="date" max={dateKey()} value={date} onChange={e=>{setDate(e.target.value);setValue(String(data.days.find(d=>d.date===e.target.value)?.pressureHpa??''))}}/></Field><Field label={t('Pressure (hPa)','فضائی دباؤ (hPa)')}><input type="number" min="800" max="1100" step="0.1" value={value} onChange={e=>setValue(e.target.value)}/></Field>{error&&<p role="alert">{error}</p>}<button className="primary" disabled={busy}>{t('Save observation','مشاہدہ محفوظ کریں')}</button></form></Modal>}
export function PinkReports(p:Props&{go:(s:string)=>void}){const t=useT();const r=reportData(p.data,p.from,p.to,zone(p.mode));return <div className="pink-reports"><Card><h2>{t('Pain ratings','درد کی درجہ بندی')}</h2><p>{r.rated?t('Recorded daily peak pain, grouped by rating.','درج کردہ روزانہ سب سے زیادہ درد، درجہ بندی کے مطابق۔'):t('No pain ratings recorded in this range.','اس مدت میں درد کی درجہ بندی درج نہیں۔')}</p><div className="month-card"><Ring parts={r.bins.map((n,i)=>({n,color:colors[i]}))} center={r.rated} label={t('rated days','درجہ بندی والے دن')}/><ul className="chart-legend">{r.bins.map((n,i)=><li key={i}><b style={{background:colors[i]}}>{r.rated?Math.round(n/r.rated*100):0}%</b><span>{['0','1–3','4–6','7–10'][i]} /10 · {n} {t('days','دن')}</span></li>)}</ul></div><p className="small muted">{t('Diary measurements, not a diagnostic score. One rating per day: check-in peak first, otherwise the maximum from timed attacks. Unrated days are excluded.','ڈائری کے پیمانے، تشخیصی اسکور نہیں۔ فی دن پہلے روزانہ اندراج کا سب سے زیادہ درد، ورنہ وقت والے دوروں کا سب سے زیادہ درد۔ بغیر درجہ بندی دن شامل نہیں۔')}</p></Card><Card><h2><Pill/>{t('Medications','ادویات')}</h2><p>{r.medicationDays} {t('days with medicine recorded','دن جن میں دوا درج ہے')}</p><details><summary>{t('View medication days','دوا والے دن دیکھیں')}</summary>{r.days.filter(d=>d.daily?.checkIn?.medicine==='yes'||d.attacks.some(a=>a.medication||a.taken)).map(d=><p key={d.date}><b>{d.date}</b> · {[d.daily?.checkIn?.medicineName,...d.attacks.map(a=>a.medication)].filter(Boolean).join(', ')||t('Name not recorded','نام درج نہیں')}</p>)}</details></Card><Card><h2><CloudSun/>{t('Daily context','روزانہ کا پس منظر')}</h2><p className="muted">{t('Observed situations, not confirmed triggers.','مشاہدہ شدہ حالات، تصدیق شدہ محرکات نہیں۔')}</p>{r.context.length?<ul className="context-report">{r.context.map(([c,n])=><li key={c}>{t(c,checkInUr[c]??c)}<b>{n}</b></li>)}</ul>:<p>{t('No daily context recorded in this range.','اس مدت میں روزانہ کا پس منظر درج نہیں۔')}</p>}</Card><Card><h2>{t('Daily activity impact','روزمرہ کاموں پر اثر')}</h2>{r.days.some(d=>d.daily?.checkIn?.impact)?r.days.filter(d=>d.daily?.checkIn?.impact).map(d=><p key={d.date}>{d.date} · {t(d.daily!.checkIn!.impact,checkInUr[d.daily!.checkIn!.impact])}</p>):<p>{t('No activity impact recorded.','روزمرہ کاموں پر اثر درج نہیں۔')}</p>}</Card><Card><h2>{t('Pressure observations','فضائی دباؤ کے مشاہدات')}</h2>{r.days.some(d=>d.daily?.pressureHpa!=null)?r.days.filter(d=>d.daily?.pressureHpa!=null).map(d=><p key={d.date}>{d.date} · {d.daily!.pressureHpa} hPa</p>):<p>{t('No readings recorded. Add one from Dashboard.','کوئی پیمائش درج نہیں۔ ڈیش بورڈ سے شامل کریں۔')}</p>}</Card><button className="primary export-report" onClick={()=>p.go('summary')}><Download size={20}/>{t('Export report','رپورٹ برآمد کریں')}</button></div>}
export function ProfilePanel({ur,setUr,children}:{ur:boolean;setUr:(v:boolean)=>void;children:ReactNode}){const t=useT();return <><Card className="profile-card"><div className="profile-avatar"><User size={34}/></div><h2>{t('Your diary','آپ کی ڈائری')}</h2><p className="muted">{t('Your diary stays in this browser. Your first-time setup is remembered on this device.','آپ کی ڈائری اسی براؤزر میں رہتی ہے۔ ابتدائی ترتیب اس ڈیوائس پر یاد رکھی جاتی ہے۔')}</p><button onClick={()=>setUr(!ur)}>{ur?'English':'اردو'}</button></Card>{children}</>}
